 rb.onclick=()=>{mode=mode?null:'ruler';pts=[];ovl.innerHTML='';rb.setAttribute('aria-pressed',!!mode);frame.classList.toggle('pickmode',!!mode);if(mode)out.innerHTML='<span class="readout">📏 Tippt auf den Anfangs- und dann auf den Endpunkt.</span>'};
