 api.toolbar.querySelector('[data-m="mess"]').onclick=e=>{const m=api.extra.querySelector('#mess');m.hidden=!m.hidden;e.currentTarget.setAttribute('aria-pressed',!m.hidden);if(!m.hidden){m.scrollIntoView({behavior:'smooth',block:'nearest'});api.emit('mess',1)}};
